let triangleAngles = [50, 65, null];
let selectedAngles = [];
let sumSelected = 0;
let missingAngle = null;
let stage = 0;
let feedbackText = 'İki açıyı seç.';
let angleButtons = [];
let calcBtn, resetBtn;

function setup() {
  createCanvas(560, 340);
  textFont('sans-serif');
  initializeGame();
}

function initializeGame() {
  resetGame();
  angleButtons = [
    { label: '50°', value: 50, x: 396, y: 100, w: 56, h: 34 },
    { label: '65°', value: 65, x: 456, y: 100, w: 56, h: 34 }
  ];
  calcBtn = { x: 396, y: 150, w: 116, h: 34 };
  resetBtn = { x: 396, y: 194, w: 116, h: 34 };
}

function resetGame() {
  selectedAngles = [];
  sumSelected = 0;
  missingAngle = null;
  stage = 0;
  feedbackText = 'İki açıyı seç.';
}

function draw() {
  background(248);
  fill(30);
  textSize(18);
  text('Üçgenin eksik açısını bul', 16, 34);

  drawPlayArea();
  drawControls();
  drawFeedback();
}

function drawPlayArea() {
  fill(255);
  stroke(210);
  rect(16, 56, 360, 220, 10);

  push();
  translate(110, 230);
  stroke(70);
  strokeWeight(2);
  line(0, 0, 120, 0);
  line(0, 0, 70, -115);
  line(120, 0, 70, -115);
  pop();

  drawAngleLabel(50, 98, 204, selectedAngles.includes(50));
  drawAngleLabel(65, 165, 204, selectedAngles.includes(65));
  drawAngleLabel(missingAngle !== null ? missingAngle : '?', 138, 88, false, true);

  fill(60);
  noStroke();
  textSize(13);
  text('Seçilenler:', 28, 78);
  let selText = selectedAngles.length ? selectedAngles.map(a => a + '°').join(' + ') : '—';
  text(selText, 28, 98);
  textSize(15);
  text('Bir üçgende iç açılar toplamı 180°', 28, 124);
}

function drawAngleLabel(value, x, y, selected, isMissing = false) {
  push();
  translate(x, y);
  fill(isMissing ? color(255, 240, 200) : selected ? color(210, 240, 220) : 255);
  stroke(selected ? color(60, 160, 90) : 120);
  rect(0, 0, 50, 28, 8);
  fill(30);
  noStroke();
  textAlign(CENTER, CENTER);
  textSize(14);
  text(String(value), 25, 14);
  pop();
}

function drawControls() {
  fill(255);
  stroke(210);
  rect(384, 56, 160, 220, 10);
  fill(30);
  textSize(13);
  text('Kontrol', 398, 78);

  for (let b of angleButtons) {
    let over = mouseX >= b.x && mouseX <= b.x + b.w && mouseY >= b.y && mouseY <= b.y + b.h;
    fill(over ? color(230, 235, 255) : 245);
    stroke(120);
    rect(b.x, b.y, b.w, b.h, 8);
    fill(20);
    noStroke();
    textAlign(CENTER, CENTER);
    textSize(15);
    text(b.label, b.x + b.w / 2, b.y + b.h / 2);
  }

  drawButton(calcBtn, 'Hesapla');
  drawButton(resetBtn, 'Sıfırla');

  fill(60);
  textAlign(LEFT, TOP);
  textSize(12);
  text('İpucu:\nÖnce toplamı bul.', 396, 244);
}

function drawButton(btn, label) {
  let over = mouseX >= btn.x && mouseX <= btn.x + btn.w && mouseY >= btn.y && mouseY <= btn.y + btn.h;
  fill(over ? color(255, 245, 210) : color(250));
  stroke(120);
  rect(btn.x, btn.y, btn.w, btn.h, 8);
  fill(20);
  noStroke();
  textAlign(CENTER, CENTER);
  textSize(14);
  text(label, btn.x + btn.w / 2, btn.y + btn.h / 2);
}

function drawFeedback() {
  fill(255);
  stroke(210);
  rect(16, 284, 528, 44, 10);
  fill(30);
  noStroke();
  textAlign(LEFT, CENTER);
  textSize(14);
  text(feedbackText, 28, 306, 500, 22);
}

function mousePressed() {
  for (let b of angleButtons) {
    if (hit(b)) {
      if (!selectedAngles.includes(b.value)) selectedAngles.push(b.value);
      else selectedAngles = selectedAngles.filter(v => v !== b.value);
      sumSelected = selectedAngles.reduce((a, v) => a + v, 0);
      feedbackText = 'Seçilen toplam: ' + sumSelected + '°';
      return;
    }
  }
  if (hit(calcBtn)) {
    if (selectedAngles.length < 2) {
      feedbackText = 'İki açıyı da seçmelisin.';
      return;
    }
    if (sumSelected === 115) {
      missingAngle = 180 - sumSelected;
      stage = 1;
      feedbackText = 'Harika! Eksik açı ' + missingAngle + '°.';
    } else {
      feedbackText = 'Toplamı kontrol et. 180°’den çıkar.';
    }
    return;
  }
  if (hit(resetBtn)) {
    resetGame();
  }
}

function hit(b) {
  return mouseX >= b.x && mouseX <= b.x + b.w && mouseY >= b.y && mouseY <= b.y + b.h;
}

let vertexX, vertexY;
let leftRayAngle, rightRayAngle;
let leftRayLength, rightRayLength;
let draggingHandle = null;
let mode = 'explore';
let angleDeg = 0;
let showHint = true;
let btnNew, btnReset;
let handleL, handleR;

function setup() {
  createCanvas(560, 340);
  textFont('sans-serif');
  initializeGame();
}

function initializeGame() {
  resetGame();
  btnNew = createButton('Yeni Çizim');
  btnNew.position(400, 94);
  btnNew.size(92, 28);
  btnNew.mousePressed(() => {
    leftRayAngle = random(-PI * 0.2, PI * 0.8);
    rightRayAngle = leftRayAngle + random(PI * 0.5, PI * 1.4);
    leftRayLength = random(70, 110);
    rightRayLength = random(70, 110);
    mode = 'explore';
    showHint = false;
  });

  btnReset = createButton('Sıfırla');
  btnReset.position(400, 132);
  btnReset.size(92, 28);
  btnReset.mousePressed(resetGame);
}

function resetGame() {
  vertexX = 180;
  vertexY = 166;
  leftRayAngle = -PI / 6;
  rightRayAngle = PI / 3;
  leftRayLength = 100;
  rightRayLength = 95;
  draggingHandle = null;
  mode = 'explore';
  showHint = true;
  angleDeg = abs(degrees((rightRayAngle - leftRayAngle + TWO_PI) % TWO_PI));
  if (angleDeg > 180) angleDeg = 360 - angleDeg;
}

function draw() {
  background(245);
  drawTitle();
  drawPlayArea();
  drawControls();
  drawFeedback();
}

function drawTitle() {
  fill(30);
  noStroke();
  rect(16, 12, 528, 36, 8);
  fill(255);
  textSize(16);
  textAlign(LEFT, CENTER);
  text('Açıyı yönle keşfet', 28, 30);
}

function drawPlayArea() {
  fill(255);
  stroke(210);
  rect(16, 56, 360, 220, 10);

  fill(240);
  noStroke();
  ellipse(vertexX, vertexY, 10, 10);

  let lx = vertexX + cos(leftRayAngle) * leftRayLength;
  let ly = vertexY + sin(leftRayAngle) * leftRayLength;
  let rx = vertexX + cos(rightRayAngle) * rightRayLength;
  let ry = vertexY + sin(rightRayAngle) * rightRayLength;

  stroke(60, 120, 255);
  strokeWeight(4);
  line(vertexX, vertexY, lx, ly);
  stroke(255, 120, 60);
  line(vertexX, vertexY, rx, ry);

  handleL = { x: lx, y: ly };
  handleR = { x: rx, y: ry };

  noStroke();
  fill(60, 120, 255);
  ellipse(lx, ly, 14, 14);
  fill(255, 120, 60);
  ellipse(rx, ry, 14, 14);

  let bis = (leftRayAngle + rightRayAngle) / 2;
  if (abs(rightRayAngle - leftRayAngle) > PI) bis += PI;
  let arcSize = abs(rightRayAngle - leftRayAngle);
  if (arcSize > PI) arcSize = TWO_PI - arcSize;

  noFill();
  stroke(60, 160, 80);
  strokeWeight(3);
  arc(vertexX, vertexY, 70, 70, leftRayAngle, rightRayAngle, false);

  fill(30);
  noStroke();
  textSize(13);
  textAlign(LEFT, TOP);
  text('Köşe', vertexX - 12, vertexY + 10);
  text('Açı: ' + nf(degrees(arcSize), 0, 0) + '°', 34, 70);
  text('Uzunluk değil, açıklık önemlidir.', 34, 90);

  if (showHint) {
    fill(0, 110, 0);
    text('Uçları sürükle.', 34, 110);
  }
}

function drawControls() {
  fill(255);
  stroke(210);
  rect(384, 56, 160, 220, 10);
  fill(40);
  noStroke();
  textSize(12);
  textAlign(LEFT, TOP);
  text('Deney: aynı köşe, farklı yön', 396, 64, 130, 40);
  text('Sürüklenecek nokta: uçlar', 396, 108, 130, 40);
  text('Amaç: açının boyunu değil yönü görmek', 396, 152, 128, 70);
}

function drawFeedback() {
  fill(255);
  stroke(210);
  rect(16, 284, 528, 44, 10);
  fill(30);
  noStroke();
  textSize(13);
  textAlign(LEFT, CENTER);
  let msg = 'Kolları çevir; köşeyi sabit tut.';
  if (abs(degrees((rightRayAngle - leftRayAngle + TWO_PI) % TWO_PI) - 180) < 5) {
    msg = 'Harika! Bu bir doğru açı. Yönler karşılıklı olduğunda 180° olur.';
  }
  text(msg, 28, 306, 500, 24);
}

function mousePressed() {
  if (dist(mouseX, mouseY, handleL.x, handleL.y) < 12) draggingHandle = 'left';
  else if (dist(mouseX, mouseY, handleR.x, handleR.y) < 12) draggingHandle = 'right';
}

function mouseDragged() {
  if (!draggingHandle) return;
  let a = atan2(mouseY - vertexY, mouseX - vertexX);
  if (draggingHandle === 'left') leftRayAngle = a;
  if (draggingHandle === 'right') rightRayAngle = a;
  angleDeg = abs(degrees((rightRayAngle - leftRayAngle + TWO_PI) % TWO_PI));
  if (angleDeg > 180) angleDeg = 360 - angleDeg;
}

function mouseReleased() {
  draggingHandle = null;
}

function touchStarted() {
  mousePressed();
  return false;
}

function touchMoved() {
  mouseDragged();
  return false;
}

function touchEnded() {
  mouseReleased();
  return false;
}

let lineType = 0; // 0=segment, 1=ray, 2=line
let draggingLeft = false;
let draggingRight = false;
let leftEndpointX = 180;
let rightEndpointX = 420;
let y = 220;
let selected = false;
let attemptCount = 0;
let hintState = 0;

function setup() {
  createCanvas(640, 360);
  textAlign(CENTER, CENTER);
  textSize(18);
}

function draw() {
  background(245, 248, 255);

  drawUI();
  drawConstruction();
  drawButtons();
  drawFeedback();
}

function drawUI() {
  fill(40);
  noStroke();
  text('Uçları incele: iki ucu da görünen çizgiyi bul.', width / 2, 30);
  text('Sürükle, değiştir ve gözlemle.', width / 2, 54);
}

function drawConstruction() {
  stroke(50);
  strokeWeight(4);

  if (lineType === 0) {
    line(leftEndpointX, y, rightEndpointX, y);
    drawEndpoints(true, true);
  } else if (lineType === 1) {
    line(leftEndpointX, y, width - 40, y);
    drawEndpoints(true, false);
    drawArrow(width - 40, y, 1);
  } else {
    line(40, y, width - 40, y);
    drawEndpoints(false, false);
    drawArrow(40, y, -1);
    drawArrow(width - 40, y, 1);
  }

  if (selected) {
    noFill();
    stroke(60, 170, 90);
    strokeWeight(3);
    ellipse((leftEndpointX + rightEndpointX) / 2, y, 300, 70);
  }
}

function drawEndpoints(showLeft, showRight) {
  noStroke();
  fill(255, 120, 80);
  if (showLeft) ellipse(leftEndpointX, y, 16, 16);
  if (showRight) ellipse(rightEndpointX, y, 16, 16);
  if (lineType === 0) {
    fill(70);
    text('A', leftEndpointX, y - 22);
    text('B', rightEndpointX, y - 22);
  }
}

function drawArrow(x, y, dir) {
  stroke(50);
  strokeWeight(3);
  line(x, y, x + dir * 18, y - 8);
  line(x, y, x + dir * 18, y + 8);
}

function drawButtons() {
  drawButton(70, 300, 160, 42, 'ÇİZGİYİ DEĞİŞTİR');
  drawButton(260, 300, 160, 42, 'SEÇ / KONTROL ET');
  drawButton(450, 300, 120, 42, 'SIFIRLA');
}

function drawButton(x, y, w, h, label) {
  stroke(120);
  fill(255);
  rect(x, y, w, h, 10);
  noStroke();
  fill(40);
  text(label, x + w / 2, y + h / 2);
}

function drawFeedback() {
  fill(70);
  noStroke();
  let msg = '';
  if (selected) {
    msg = 'Tebrikler! İki ucu belli olan çizgi doğru parçasıdır.';
    fill(40, 130, 70);
  } else if (attemptCount > 0) {
    msg = 'Uçlara bak: tek yönde uzuyorsa ışın, iki yönde uzuyorsa doğru, iki uçluysa doğru parçası.';
    fill(180, 90, 30);
  } else {
    msg = 'İpucu: Uçların ikisini de görebiliyor musun?';
  }
  text(msg, width / 2, 88);
}

function mousePressed() {
  if (dist(mouseX, mouseY, leftEndpointX, y) < 18) draggingLeft = true;
  if (dist(mouseX, mouseY, rightEndpointX, y) < 18) draggingRight = true;

  if (insideRect(mouseX, mouseY, 70, 300, 160, 42)) {
    lineType = (lineType + 1) % 3;
    selected = false;
    attemptCount++;
  } else if (insideRect(mouseX, mouseY, 260, 300, 160, 42)) {
    attemptCount++;
    selected = (lineType === 0);
  } else if (insideRect(mouseX, mouseY, 450, 300, 120, 42)) {
    resetGame();
  }
}

function mouseDragged() {
  if (draggingLeft && lineType === 0) {
    leftEndpointX = constrain(mouseX, 60, rightEndpointX - 30);
  }
  if (draggingRight && lineType === 0) {
    rightEndpointX = constrain(mouseX, leftEndpointX + 30, width - 60);
  }
}

function mouseReleased() {
  draggingLeft = false;
  draggingRight = false;
}

function keyPressed() {
  if (key === 'r' || key === 'R') resetGame();
}

function resetGame() {
  lineType = 0;
  leftEndpointX = 180;
  rightEndpointX = 420;
  selected = false;
  attemptCount = 0;
  hintState = 0;
}

function insideRect(px, py, x, y, w, h) {
  return px >= x && px <= x + w && py >= y && py <= y + h;
}

let vertices = [];
let selected = 1; // 0 kare, 1 üçgen, 2 beşgen, 3 altıgen
let shapes = [4, 3, 5, 6];
let names = ['Kare', 'Üçgen', 'Beşgen', 'Altıgen'];
let answers = ['360°', '180°', '540°', '720°'];

function setup() {
  createCanvas(900, 650);
  textFont('Arial');
}

function draw() {
  background(248);
  drawTitle();
  drawQuestionCard();
  drawShapePanel();
  drawOptions();
  drawExplanation();
}

function drawTitle() {
  fill(30);
  textAlign(CENTER, CENTER);
  textSize(26);
  text('İç Açılar Toplamı: Hangi Şekil 180°?', width/2, 32);
}

function drawQuestionCard() {
  fill(255);
  stroke(220);
  rect(40, 60, 820, 110, 14);
  noStroke();
  fill(40);
  textAlign(LEFT, TOP);
  textSize(18);
  text('Aşağıdaki geometrik şekillerden hangisinin iç açıları toplamı her zaman 180 derecedir?', 60, 85, 780, 60);
  textSize(16);
  fill(80);
  text('Doğru cevabı bulmak için şekilleri inceleyin.', 60, 130);
}

function drawShapePanel() {
  fill(255);
  stroke(220);
  rect(40, 190, 820, 260, 14);
  noStroke();
  textAlign(CENTER, CENTER);
  textSize(16);
  fill(40);
  text('Şekiller', width/2, 210);

  let centers = [160, 360, 560, 760];
  for (let i = 0; i < 4; i++) {
    let x = centers[i];
    let y = 330;
    drawPolygon(x, y, 70, shapes[i], i === selected);
    fill(30);
    text(names[i], x, 420);
    fill(90);
    text(answers[i], x, 440);
  }
}

function drawPolygon(cx, cy, r, n, highlighted) {
  push();
  translate(cx, cy);
  if (highlighted) {
    noFill();
    stroke(255, 180, 0);
    strokeWeight(4);
    ellipse(0, 0, 170, 170);
  }
  stroke(60);
  strokeWeight(3);
  fill(highlighted ? color(255, 248, 210) : color(235));
  beginShape();
  for (let i = 0; i < n; i++) {
    let angle = TWO_PI * i / n - HALF_PI;
    vertex(cos(angle) * r, sin(angle) * r);
  }
  endShape(CLOSE);
  pop();
}

function drawOptions() {
  fill(255);
  stroke(220);
  rect(40, 470, 820, 80, 14);
  noStroke();
  fill(40);
  textAlign(LEFT, CENTER);
  textSize(18);
  text('Seçenekler:', 60, 505);
  textSize(17);
  let opts = ['A) Kare', 'B) Üçgen', 'C) Beşgen', 'D) Altıgen'];
  let x = 180;
  for (let i = 0; i < opts.length; i++) {
    fill(i === selected ? color(0, 120, 220) : 60);
    text(opts[i], x + i * 170, 505);
  }
}

function drawExplanation() {
  fill(255);
  stroke(220);
  rect(40, 565, 820, 70, 14);
  noStroke();
  textAlign(LEFT, CENTER);
  textSize(16);
  fill(30, 120, 60);
  text('Doğru cevap: B) Üçgen — Üçgenin iç açıları toplamı her zaman 180°dir.', 60, 600);
}

let tri;
let showStep = 0;
let steps;

function setup() {
  createCanvas(800, 520);
  textFont('Arial');
  steps = [
    { title: '1) Kenarları incele', text: 'Üçgenin kenarları 6 cm, 6 cm ve 8 cm.' },
    { title: '2) Eşit kenar var mı?', text: 'İki kenar eşit: 6 cm = 6 cm.' },
    { title: '3) Sonuç', text: 'İki kenarı eşit olan üçgen ikizkenar üçgendir.' }
  ];
}

function draw() {
  background(248);
  drawHeader();
  drawTriangle();
  drawInfoPanel();
  drawStepButtons();
}

function drawHeader() {
  fill(30);
  noStroke();
  textSize(24);
  textStyle(BOLD);
  text('Kenarlarına Göre Üçgen Türü', 24, 34);
  textStyle(NORMAL);
  textSize(14);
  fill(70);
  text('Soruda verilen 6 cm, 6 cm ve 8 cm kenarlarına göre üçgeni inceleyelim.', 24, 58);
}

function drawTriangle() {
  // Triangle area
  const ax = 140, ay = 360;
  const bx = 300, by = 360;
  const cx = 220, cy = 190;

  // Triangle
  stroke(40);
  strokeWeight(3);
  fill(255, 245, 200);
  triangle(ax, ay, bx, by, cx, cy);

  // Vertex labels
  noStroke();
  fill(20);
  textSize(16);
  text('A', ax - 18, ay + 20);
  text('B', bx + 8, by + 20);
  text('C', cx - 6, cy - 10);

  // Side labels with colored highlights
  strokeWeight(2);
  stroke(220, 70, 70);
  line(ax, ay, cx, cy);
  stroke(220, 70, 70);
  line(bx, by, cx, cy);
  stroke(70, 130, 220);
  line(ax, ay, bx, by);

  noStroke();
  fill(220, 70, 70);
  textSize(18);
  text('6 cm', 150, 250);
  text('6 cm', 248, 250);
  fill(70, 130, 220);
  text('8 cm', 198, 385);

  // Equal marks on equal sides
  stroke(220, 70, 70);
  strokeWeight(2);
  line(178, 288, 170, 300);
  line(186, 282, 178, 294);
  line(222, 288, 230, 300);
  line(214, 282, 222, 294);
}

function drawInfoPanel() {
  const x = 420, y = 110, w = 340, h = 310;
  noStroke();
  fill(255);
  rect(x, y, w, h, 18);

  fill(40);
  textSize(20);
  textStyle(BOLD);
  text('Adım Adım Çözüm', x + 20, y + 35);
  textStyle(NORMAL);

  const s = steps[showStep];
  fill(60);
  textSize(18);
  text(s.title, x + 20, y + 80);

  fill(30);
  textSize(16);
  textLeading(24);
  text(s.text, x + 20, y + 120, w - 40, 120);

  // Key rule box
  fill(240, 248, 255);
  stroke(150, 190, 230);
  strokeWeight(1.5);
  rect(x + 20, y + 220, w - 40, 65, 12);
  noStroke();
  fill(35, 90, 150);
  textSize(16);
  text('Kural: En az iki kenar eşitse → ikizkenar üçgen', x + 35, y + 250, w - 70, 40);
}

function drawStepButtons() {
  const baseY = 450;
  for (let i = 0; i < 3; i++) {
    const bx = 120 + i * 150;
    const bw = 120;
    const bh = 34;
    const active = (i === showStep);
    stroke(active ? color(60, 130, 220) : color(180));
    strokeWeight(active ? 2.5 : 1);
    fill(active ? color(220, 235, 255) : color(245));
    rect(bx, baseY, bw, bh, 10);
    noStroke();
    fill(30);
    textAlign(CENTER, CENTER);
    textSize(14);
    text('Adım ' + (i + 1), bx + bw / 2, baseY + bh / 2 + 1);
  }
  textAlign(LEFT, BASELINE);

  fill(90);
  textSize(13);
  text('Adımlar arasında geçiş için klavyeden 1, 2, 3 tuşlarını kullanın.', 24, 494);
}

function keyPressed() {
  if (key === '1') showStep = 0;
  if (key === '2') showStep = 1;
  if (key === '3') showStep = 2;
}

let draggableAngle;
let targetAngle;
let isMatched;
let feedbackText;
let attempts;
let dragging;
let controlBtn;
let resetBtn;
let centerX = 196;
let centerY = 166;
let radius = 78;

function setup() {
  createCanvas(560, 340);
  initializeGame();
}

function initializeGame() {
  targetAngle = radians(35);
  draggableAngle = radians(130);
  isMatched = false;
  feedbackText = 'Mavi kolu sürükle.';
  attempts = 0;
  dragging = false;
  controlBtn = {x: 406, y: 118, w: 112, h: 32, label: 'Kontrol'};
  resetBtn = {x: 406, y: 164, w: 112, h: 32, label: 'Sıfırla'};
}

function resetGame() {
  initializeGame();
}

function draw() {
  background(248);
  drawLayout();
  drawTitle();
  drawPlayArea();
  drawControls();
  drawFeedback();
}

function drawLayout() {
  noFill();
  stroke(220);
  rect(16, 56, 360, 220, 10);
  rect(384, 56, 160, 220, 10);
  rect(16, 284, 528, 44, 10);
}

function drawTitle() {
  noStroke();
  fill(30);
  textSize(16);
  textAlign(LEFT, CENTER);
  text('Karşılıklı Açı Eşleştirme', 24, 30);
}

