}

function overButton(btn, mx, my) {
  return mx >= btn.x && mx <= btn.x + btn.w && my >= btn.y && my <= btn.y + btn.h;
}

function checkMatch() {
  let diff = angleDifference(draggableAngle, targetAngle + PI);
  if (diff < 0.16) {
    isMatched = true;
    feedbackText = 'Tebrikler! Karşılıklı açılar eşittir.';
  } else {
    isMatched = false;
    feedbackText = 'Tam karşıya getir. Karşılıklı açılar eşit olur.';
  }
}

function angleDifference(a, b) {
  let d = abs(a - b) % TWO_PI;
  return min(d, TWO_PI - d);
}

