function mousePressed() {
  if (handleButtons(mouseX, mouseY)) return;
  for (let i = pieces.length - 1; i >= 0; i--) {
    let p = pieces[i];
    if (mouseX >= p.x && mouseX <= p.x + p.w && mouseY >= p.y && mouseY <= p.y + p.h) {
      draggingPiece = p;
      offsetX = mouseX - p.x;
      offsetY = mouseY - p.y;
      p.placed = false;
      if (slots[p.target].value === p.value) slots[p.target].value = null;
      return;
    }
  }
}

function mouseDragged() {
  if (draggingPiece) {
    draggingPiece.x = mouseX - offsetX;
    draggingPiece.y = mouseY - offsetY;
  }
}

function mouseReleased() {
  if (!draggingPiece) return;
  let p = draggingPiece;
  draggingPiece = null;
  let placed = false;
  for (let i = 0; i < slots.length; i++) {
    let s = slots[i];
    if (mouseX > s.x && mouseX < s.x + s.w && mouseY > s.y && mouseY < s.y + s.h && s.value === null) {
      p.x = s.x + 19;
      p.y = s.y + 28;
      s.value = p.value;
      p.placed = true;
      p.target = i;
      placed = true;
      break;
    }
  }
  if (!placed) {
    p.x = p.homeX;
    p.y = p.homeY;
  }
}

function handleButtons(x, y) {
  for (let b of buttons) {
    if (x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h) {
      if (b.action === 'check') checkAnswer();
      if (b.action === 'reset') initializeGame();
      return true;
    }
  }
  return false;
}

function checkAnswer() {
  checked = true;
  let a = slots[0].value;
  let b = slots[1].value;
  if (a === 48 && b === 67 || a === 67 && b === 48) {
    totalAngle = 115;
    thirdAngle = 65;
    success = true;
    feedbackMsg = 'Harika! İki açı 115° etti, kalan açı 65°.';
  } else if (a !== null && b !== null) {
    totalAngle = (a || 0) + (b || 0);
    thirdAngle = 180 - totalAngle;
    success = false;
    feedbackMsg = 'Henüz olmadı. İki açının toplamını kontrol et ve üçgenin 180° olduğunu hatırla.';
  } else {
    success = false;
    thirdAngle = null;
    feedbackMsg = 'Önce iki açıyı da üçgene yerleştir.';
  }
}

