    }
  }
}

function drawCard(c) {
  fill(255, 236, 190);
  stroke(190, 140, 40);
  rect(c.x, c.y, c.w, c.h, 8);
  fill(70);
  noStroke();
  textAlign(CENTER, CENTER);
  textSize(16);
  text(c.value + '°', c.x + c.w / 2, c.y + c.h / 2);
}

function drawCardValueInSlot(id, x, y) {
  let c = cards.find(v => v.id === id);
  if (c && c.placed) {
    fill(255, 236, 190);
    stroke(190, 140, 40);
    rect(x - 30, y - 18, 60, 34, 8);
    fill(70);
    noStroke();
    textSize(16);
    textAlign(CENTER, CENTER);
    text(c.value + '°', x, y);
  }
}

