function mousePressed() {
  if (hitButton(404, 140, 112, 30)) {
    checked = true;
    updateCheck();
    return;
  }
  if (hitButton(404, 180, 112, 30)) {
    resetGame();
    return;
  }
  if (hitTriangleGuessArea()) {
    missingAngleGuess = cycleGuess(missingAngleGuess);
    feedbackText = 'Tahmin değişti: ' + missingAngleGuess + '°';
    return;
  }
  for (let i = cards.length - 1; i >= 0; i--) {
    let c = cards[i];
    if (mouseX > c.x && mouseX < c.x + c.w && mouseY > c.y && mouseY < c.y + c.h) {
      draggingId = c.id;
      dragOffsetX = mouseX - c.x;
      dragOffsetY = mouseY - c.y;
      c.placed = false;
      return;
    }
  }
}

function mouseDragged() {
  if (draggingId) {
    let c = cards.find(v => v.id === draggingId);
    c.x = mouseX - dragOffsetX;
    c.y = mouseY - dragOffsetY;
  }
}

function mouseReleased() {
  if (!draggingId) return;
  let c = cards.find(v => v.id === draggingId);
  if (overSlot(c, slots[0])) {
    c.x = slots[0].x + 28;
    c.y = slots[0].y + 4;
    c.placed = true;
  } else if (overSlot(c, slots[1])) {
    c.x = slots[1].x + 28;
    c.y = slots[1].y + 4;
    c.placed = true;
  } else {
    c.placed = false;
  }
  draggingId = null;
  sumValue = null;
  updateSlotState();
}

function touchStarted() { mousePressed(); return false; }
function touchMoved() { mouseDragged(); return false; }
function touchEnded() { mouseReleased(); return false; }

function updateSlotState() {
  slot45Filled = cards.find(c => c.id === 'c45').placed;
  slot65Filled = cards.find(c => c.id === 'c65').placed;
  if (slot45Filled && slot65Filled) {
    sumValue = 110;
    feedbackText = 'İki açıyı gördün. Şimdi 180° den çıkar.';
  } else {
    feedbackText = 'Kartları üçgene bırak.';
  }
}

function updateCheck() {
  updateSlotState();
  if (slot45Filled && slot65Filled) {
    let correctGuess = missingAngleGuess === 70;
    isCorrect = correctGuess;
    if (correctGuess) {
      feedbackText = 'Harika! 45° + 65° = 110°. 180° - 110° = 70°.';
    } else {
      feedbackText = 'Toplam doğru, ama eksik açı 70° olmalı.';
    }
  } else {
    isCorrect = false;
    feedbackText = 'Önce iki kartı yerleştir.';
  }
}

function hitButton(x, y, w, h) {
  return mouseX >= x && mouseX <= x + w && mouseY >= y && mouseY <= y + h;
}

function hitTriangleGuessArea() {
  return mouseX >= 64 && mouseX <= 320 && mouseY >= 150 && mouseY <= 240;
}

function cycleGuess(v) {
  let arr = [30, 40, 50, 60, 70, 80, 90];
  let i = arr.indexOf(v);
  return arr[(i + 1) % arr.length];
}

function overSlot(c, s) {
  return c.x + c.w / 2 > s.x && c.x + c.w / 2 < s.x + s.w && c.y + c.h / 2 > s.y && c.y + c.h / 2 < s.y + s.h;
}

let fixedAngle = 35;
let adjustableAngle = 90;
let sumAngle = 0;
let checked = false;
let isCorrect = false;
let handleX = 250;
let dragging = false;

function setup() {
  createCanvas(560, 340);
  initializeGame();
}

function initializeGame() {
  resetGame();
}

function resetGame() {
  fixedAngle = 35;
  adjustableAngle = 90;
  sumAngle = fixedAngle + adjustableAngle;
  checked = false;
  isCorrect = false;
  handleX = map(adjustableAngle, 10, 170, 150, 330);
}

function draw() {
  background(248);
  drawBoxes();
  drawTitle();
  drawPlayArea();
  drawControls();
  drawFeedback();
}

function drawBoxes() {
  noFill();
  stroke(210);
  rect(16, 12, 528, 36, 8);
  rect(16, 56, 360, 220, 8);
  rect(384, 56, 160, 220, 8);
  rect(16, 284, 528, 44, 8);
}

function drawTitle() {
  noStroke();
  fill(40);
  textSize(15);
  textAlign(LEFT, CENTER);
  text('Düz çizgi yap: açıyı ayarla', 28, 30);
}

function drawPlayArea() {
  push();
  translate(46, 100);
  stroke(70);
  strokeWeight(4);
  line(40, 120, 290, 120);

  // fixed angle arc
  noFill();
  stroke(70, 120, 220);
  strokeWeight(5);
  let end1 = radians(180 - fixedAngle);
  arc(40, 120, 90, 90, PI, end1);

  // adjustable angle arc
  stroke(230, 120, 60);
  let adjEnd = radians(180 - fixedAngle - adjustableAngle);
  if (adjEnd < 0) adjEnd = 0;
  arc(40, 120, 120, 120, radians(180 - fixedAngle), radians(180));

  // vertex
  noStroke();
  fill(40);
  ellipse(40, 120, 10, 10);

  // draggable handle on slider concept inside play area
  fill(255);
  stroke(120);
  rect(120, 170, 180, 18, 9);
  fill(80, 180, 100);
  noStroke();
  let barX = map(adjustableAngle, 10, 170, 120, 300);
  rect(120, 170, barX - 120, 18, 9);
  fill(255);
  stroke(60);
  ellipse(barX, 179, 22, 22);

  fill(40);
  noStroke();
  textSize(13);
  textAlign(LEFT, TOP);
  text('Sabit açı: 35°', 150, 0);
  text('Ayarlanabilir açı', 150, 18);
  text('Toplam: ' + sumAngle + '°', 150, 36);
  pop();

  // draggable slider knob interaction hint
  fill(60);
  noStroke();
  textSize(12);
  textAlign(LEFT, CENTER);
  text('Sürükle', 170, 247);
}

function drawControls() {
  fill(40);
  noStroke();
  textSize(13);
  textAlign(LEFT, TOP);
  text('Hedef: 180°', 398, 70);
  text('Bul: 145°', 398, 92);

  drawButton(398, 122, 112, 34, 'Kontrol', color(70, 140, 220));
  drawButton(398, 166, 112, 34, 'Sıfırla', color(200, 90, 90));

  fill(60);
  textSize(12);
  text('İpucu: 180° - 35°', 398, 214);
  text('=' + (180 - fixedAngle) + '°', 398, 232);
}

function drawButton(x, y, w, h, label, c) {
  stroke(180);
  fill(c);
  rect(x, y, w, h, 8);
  noStroke();
  fill(255);
  textAlign(CENTER, CENTER);
  textSize(13);
  text(label, x + w / 2, y + h / 2 + 1);
}

function drawFeedback() {
  fill(40);
  noStroke();
  textAlign(LEFT, CENTER);
  textSize(13);
  let msg = 'Sürgüyü kullan, sonra Kontrol’e bas.';
  if (checked) {
    msg = isCorrect ? 'Harika! 35° + 145° = 180°.' : 'Tam olmadı. Toplam 180° olmalı.';
  }
  text(msg, 28, 306);
}

function mousePressed() {
  if (mouseX > 398 && mouseX < 510 && mouseY > 122 && mouseY < 156) {
    sumAngle = fixedAngle + adjustableAngle;
    checked = true;
    isCorrect = abs(sumAngle - 180) < 0.5;
  } else if (mouseX > 398 && mouseX < 510 && mouseY > 166 && mouseY < 200) {
    resetGame();
  }

  let barY = 279;
  if (mouseX > 166 && mouseX < 346 && mouseY > 241 && mouseY < 261) {
    dragging = true;
    updateAdjustableFromMouse();
  }
}

function mouseDragged() {
  if (dragging) {
    updateAdjustableFromMouse();
  }
}

function mouseReleased() {
  dragging = false;
}

function updateAdjustableFromMouse() {
  adjustableAngle = constrain(round(map(mouseX, 166, 346, 10, 170)), 10, 170);
  sumAngle = fixedAngle + adjustableAngle;
  handleX = map(adjustableAngle, 10, 170, 166, 346);
  checked = false;
}

function touchStarted() {
  mousePressed();
  return false;
}

function touchMoved() {
  mouseDragged();
  return false;
}

function touchEnded() {
  mouseReleased();
  return false;
}
